#include "../Source/PluginEditor.h"
#include <iostream>
#include <stdexcept>
namespace {
void need(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
void set(SpaceInfinityProcessor& p,const char* id,float value){auto* a=p.state.getParameter(id);need(a!=nullptr,"pitch parameter exists");a->setValueNotifyingHost(a->convertTo0to1(value));}
juce::Component* named(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* found=named(*child,name))return found;return nullptr;}
juce::MouseEvent mouse(juce::Component& c){return {juce::Desktop::getInstance().getMainMouseSource(),{5,5},{},1,0,0,0,0,&c,&c,juce::Time::getCurrentTime(),{5,5},juce::Time::getCurrentTime(),1,false};}
double pitch(float up,float down,float host,int midi=-1,bool changeHeld=false){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","distEnabled","osc2Enabled"})set(*p,id,0);set(*p,"routeA",0);set(*p,"wave",2);set(*p,"mix",0);set(*p,"noiseLevel",0);set(*p,"subLevel",0);set(*p,"engineMode",1);set(*p,"analogueCharacter",0);set(*p,"osc1PhaseReset",1);set(*p,"ampSustain",1);set(*p,"attack",0);set(*p,"gain",.1f);set(*p,"pitchUpLimit",up);set(*p,"pitchDownLimit",down);set(*p,"pitchBend",host);p->prepareToPlay(48000,128);juce::AudioBuffer<float> b(2,128);float previous=0;int crossings=0,first=-1,last=-1;for(int block=0;block<160;++block){juce::MidiBuffer m;if(block==0){m.addEvent(juce::MidiMessage::noteOn(1,69,.8f),0);if(midi>=0)m.addEvent(juce::MidiMessage::pitchWheel(1,midi),0);}if(changeHeld&&block==50)set(*p,"pitchUpLimit",24);p->processBlock(b,m);for(int i=0;i<128;++i){const float v=b.getSample(0,i);if(block>90&&v>=0&&previous<0){if(first<0)first=block*128+i;last=block*128+i;++crossings;}previous=v;}}need(crossings>4,"audible pitched output");return 48000.0*(crossings-1)/(last-first);}
}
int runPitchTravelSmoke(){try{
 auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());editor->setVisible(true);auto* wheel=dynamic_cast<SpringPitchWheel*>(named(*editor,"Pitch Wheel"));auto* up=dynamic_cast<juce::Slider*>(named(*editor,"Pitch up limit"));auto* down=dynamic_cast<juce::Slider*>(named(*editor,"Pitch down limit"));auto* keys=dynamic_cast<juce::MidiKeyboardComponent*>(named(*editor,"Playable piano keyboard"));auto* sub=named(*editor,"Sub oscillator");need(wheel&&up&&down&&keys&&sub,"main pitch travel controls exist");need(editor->getWidth()==1280&&editor->getHeight()==760,"default editor uses the balanced wide layout");auto* lfo=named(*editor,"LFO 1 curve");need(lfo&&lfo->getWidth()>lfo->getHeight()*1.4,"main LFO graph stays landscape at the default size");up->setValue(12,juce::sendNotificationSync);down->setValue(24,juce::sendNotificationSync);need(wheel->getMinimum()==-24&&wheel->getMaximum()==12&&std::abs(wheel->valueToProportionOfLength(0)-.5)<1e-8,"asymmetric limits keep zero centred");need(wheel->proportionOfLengthToValue(0)==-24&&wheel->proportionOfLengthToValue(1)==12,"wheel reaches chosen stops exactly");wheel->setValue(12,juce::sendNotificationSync);wheel->mouseUp(mouse(*wheel));need(wheel->getValue()==0&&p->state.getRawParameterValue("pitchBend")->load()==0&&up->getValue()==12&&down->getValue()==24,"spring returns to zero while limits remain saved");
 for(auto size:{juce::Point<int>(800,760),{1000,790},{1180,820},{1280,760},{1500,950}}){editor->setSize(size.x,size.y);need(wheel->getY()>size.y-90&&wheel->getRight()<194,"pitch wheel moved to bottom left beside sub");for(auto* c:std::array<juce::Component*,5>{wheel,up,down,keys,sub})need(editor->getLocalBounds().contains(c->getBounds()),"pitch, keyboard and sub fit every window size");auto* hit=editor->getComponentAt(sub->getBounds().getCentre());need(hit==sub||sub->isParentOf(hit),"sub controls remain visible above the macro panel");need(!keys->getBounds().intersects(wheel->getBounds())&&!keys->getBounds().intersects(sub->getBounds()),"keyboard clears pitch wheel and sub");}
 up->setValue(0,juce::sendNotificationSync);down->setValue(0,juce::sendNotificationSync);need(!wheel->isEnabled(),"both zero limits disable pitch travel");up->setValue(7,juce::sendNotificationSync);need(wheel->isEnabled()&&wheel->getMaximum()==7&&wheel->getMinimum()==0&&wheel->valueToProportionOfLength(0)==.5,"single-sided travel keeps centre");juce::MemoryBlock state;p->getStateInformation(state);auto recall=std::make_unique<SpaceInfinityProcessor>();recall->setStateInformation(state.getData(),int(state.getSize()));need(recall->state.getRawParameterValue("pitchUpLimit")->load()==7&&recall->state.getRawParameterValue("pitchDownLimit")->load()==0,"independent endpoints recall");

 const auto page=[&](const juce::String& name){for(auto* c:editor->getChildren())if(auto* b=dynamic_cast<juce::TextButton*>(c))if(b->getButtonText()==name){b->onClick();return;}throw std::runtime_error("page tab missing");};page("FX");need(!keys->isVisible()&&!sub->isVisible(),"keyboard and sub hide on FX");set(*p,"source",1);page("MAIN");need(keys->isVisible()&&!sub->isVisible(),"sampler page keeps keyboard and clears sub panel");set(*p,"source",0);page("MAIN");need(keys->isVisible()&&sub->isVisible(),"synth page restores keyboard and sub");
 p->loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","distEnabled"})set(*p,id,0);set(*p,"release",.01f);p->prepareToPlay(48000,128);
 editor->setSize(1000,760);editor->setTopLeftPosition(0,0);
 editor->addToDesktop(0);editor->setVisible(true);editor->toFront(true);
 const auto key=keys->getRectangleForKey(60);const juce::Point<float> keyPosition{key.getCentreX(),float(keys->getHeight()-8)};
 const auto keyEvent=[&](bool pressed){return juce::MouseEvent{juce::Desktop::getInstance().getMainMouseSource(),keyPosition,pressed?juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier):juce::ModifierKeys(),1,0,0,0,0,keys,keys,juce::Time::getCurrentTime(),keyPosition,juce::Time::getCurrentTime(),1,false};};
 // A 760-high editor can extend behind a small CI desktop's taskbar. Put
 // the tested key, not the whole oversized window, inside the visible work area.
 const auto* display=juce::Desktop::getInstance().getDisplays().getDisplayForRect(editor->getScreenBounds());
 const auto screenKey=keys->localPointToGlobal(keyPosition.toInt());
 if(display)editor->setTopLeftPosition(editor->getPosition()+display->userArea.getCentre()-screenKey);
 std::cout<<"Keyboard native window "<<editor->getBounds().toString()<<" key "<<keyPosition.toString()<<" screen "<<keys->localPointToGlobal(keyPosition.toInt()).toString()<<std::endl;
 need(keys->getNoteAndVelocityAtPosition(keyPosition).note==60,"native keyboard hit test selects the displayed key");static_cast<juce::Component*>(keys)->mouseDown(keyEvent(true));need(p->keyboardState.isNoteOn(1,60),"clicking the on-screen keyboard triggers its note");juce::AudioBuffer<float> keyboardAudio(2,128);float peak=0;for(int block=0;block<50;++block){juce::MidiBuffer midi;p->processBlock(keyboardAudio,midi);peak=juce::jmax(peak,keyboardAudio.getMagnitude(0,0,128));}need(peak>.0001f,"GUI keyboard notes reach native DSP without host MIDI");static_cast<juce::Component*>(keys)->mouseUp(keyEvent(false));need(!p->keyboardState.isNoteOn(1,60),"keyboard mouse release clears its note");for(int block=0;block<180;++block){juce::MidiBuffer midi;p->processBlock(keyboardAudio,midi);}need(keyboardAudio.getMagnitude(0,0,128)<1e-5f,"keyboard release leaves no stuck note");editor->removeFromDesktop();
 need(std::abs(pitch(12,24,24)-880)<3,"host pitch clips at selected up stop");need(std::abs(pitch(24,7,-24)-440*std::exp2(-7.0/12))<2,"host pitch clips at selected down stop");need(std::abs(pitch(7,24,0,16383)-440*std::exp2(7.0/12))<3,"MIDI up follows its own limit");need(std::abs(pitch(24,24,0,0)-110)<1,"MIDI down reaches minus24");need(std::abs(pitch(0,0,24,16383)-440)<2,"zero limits suppress host and MIDI bend");need(std::abs(pitch(12,24,0,12288,true)-880)<3,"changing limits rescales a held MIDI wheel without a new MIDI event");
 std::cout<<"Pitch travel: bottom-left placement, independent stops, centred spring return, recall, host/MIDI bounds, held-wheel rescaling and playable keyboard passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Pitch travel: "<<e.what()<<'\n';return 184;}}
